285	func (s *Store) createAPIKey(orgID, userID, name string, now time.Time) (APIKey, error) {
286		if _, ok := s.members[memberKey{orgID, userID}]; !ok {
287			return APIKey{}, ErrNotFound
288		}
289		name = strings.TrimSpace(name)
290		if name == "" {
291			name = "API key"
292		}
293		k := APIKey{ID: s.newID("key"), OrgID: orgID, UserID: userID, Name: name, Token: NewToken("tly_"), CreatedAt: now.UTC()}
294		s.apiKeys[k.ID] = k
295		s.keysByToken[k.Token] = k.ID
296		return k, nil
297	}
