// TestEmailsArePerOrganization checks that two organizations can each have a customer with the same email address, and that
// each finds, reuses and changes only its own.
func TestEmailsArePerOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := e.CreateCustomer(e.Acme, "Jane Acme", "jane@example.com")
	globex := e.CreateCustomer(e.Globex, "Jane Globex", "Jane@Example.com")

	find := func(org apitest.Org, email string) []store.Customer {
		t.Helper()
		var page struct {
			Items []store.Customer `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/customers?email="+email, org.Key, nil, &page)
		return page.Items
	}
	if got := find(e.Acme, "jane@example.com"); len(got) != 1 || got[0].ID != acme.ID {
		t.Fatalf("Acme finds %+v, want its own customer %s", got, acme.ID)
	}
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != globex.ID {
		t.Fatalf("Globex finds %+v, want its own customer %s", got, globex.ID)
	}

	// Acme's address is taken within Acme, but not within Globex.
	if r := e.Do("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "JANE@example.com"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("duplicate within Acme: %s", r)
	}

	// Moving Acme's customer to a new address frees the old one in Acme only.
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+acme.ID, e.Acme.Key, map[string]string{"email": "jane.acme@example.com"}, nil)
	if got := find(e.Acme, "jane@example.com"); len(got) != 0 {
		t.Fatalf("Acme still finds the old address: %+v", got)
	}
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != globex.ID {
		t.Fatalf("Globex lost its customer when Acme changed its address: %+v", got)
	}

	// Deleting Globex's customer leaves Acme's alone.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+globex.ID, e.Globex.Key, nil, nil)
	if got := find(e.Acme, "jane.acme@example.com"); len(got) != 1 || got[0].ID != acme.ID {
		t.Fatalf("Acme lost its customer when Globex deleted one: %+v", got)
	}
}

