// TestOtherOrgsObjectsLookUnknown checks that an ID in the path that belongs to another organization is answered exactly
// as an ID that does not exist, and that the request changes nothing.
func TestOtherOrgsObjectsLookUnknown(t *testing.T) {
	e := apitest.New(t)
	cus := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Pro", "USD", "10.00")
	inv := createInvoice(t, e, e.Acme, cus.ID)
	sub := createSubscription(t, e, e.Acme, cus.ID, plan.ID)
	ep := createEndpoint(t, e, e.Acme, "https://hooks.acme.example/tally")

	cases := []struct {
		name, method, path, id, missing string
		body                            any
	}{
		{"invoice", "GET", "/v1/invoices/%s", inv, "in_999999", nil},
		{"invoice lines", "GET", "/v1/invoices/%s/lines", inv, "in_999999", nil},
		{"pay invoice", "POST", "/v1/invoices/%s/pay", inv, "in_999999", map[string]string{"payment_method": "pm_card"}},
		{"void invoice", "POST", "/v1/invoices/%s/void", inv, "in_999999", nil},
		{"customer", "GET", "/v1/customers/%s", cus.ID, "cus_999999", nil},
		{"update customer", "PATCH", "/v1/customers/%s", cus.ID, "cus_999999", map[string]string{"name": "Mallory"}},
		{"delete customer", "DELETE", "/v1/customers/%s", cus.ID, "cus_999999", nil},
		{"plan", "GET", "/v1/plans/%s", plan.ID, "plan_999999", nil},
		{"update plan", "PATCH", "/v1/plans/%s", plan.ID, "plan_999999", map[string]string{"name": "Mallory"}},
		{"subscription", "GET", "/v1/subscriptions/%s", sub, "sub_999999", nil},
		{"update subscription", "PATCH", "/v1/subscriptions/%s", sub, "sub_999999", map[string]int{"quantity": 9}},
		{"cancel subscription", "POST", "/v1/subscriptions/%s/cancel", sub, "sub_999999", nil},
		{"report usage", "POST", "/v1/subscriptions/%s/usage", sub, "sub_999999", map[string]int{"quantity": 1}},
		{"webhook endpoint", "GET", "/v1/webhook-endpoints/%s", ep, "we_999999", nil},
		{"update webhook endpoint", "PATCH", "/v1/webhook-endpoints/%s", ep, "we_999999", map[string]bool{"enabled": false}},
		{"delete webhook endpoint", "DELETE", "/v1/webhook-endpoints/%s", ep, "we_999999", nil},
		{"webhook deliveries", "GET", "/v1/webhook-endpoints/%s/deliveries", ep, "we_999999", nil},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			foreign := e.Do(c.method, fmt.Sprintf(c.path, c.id), e.Globex.Key, c.body)
			unknown := e.Do(c.method, fmt.Sprintf(c.path, c.missing), e.Globex.Key, c.body)
			if foreign.Code != http.StatusNotFound || foreign.Map(t)["error"] != "not_found" {
				t.Fatalf("another organization's object: %s", foreign)
			}
			if unknown.Code != foreign.Code || !bytes.Equal(unknown.Body, foreign.Body) {
				t.Fatalf("another organization's object answers %s, an unknown one %s", foreign, unknown)
			}
		})
	}

	// Nothing of Acme's changed, and Acme still reads all of it.
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv, e.Acme.Key, nil, nil)
	var got store.Invoice
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv+"/lines", e.Acme.Key, nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+cus.ID, e.Acme.Key, nil, &got)
	var c store.Customer
	e.MustDo(http.StatusOK, "GET", "/v1/customers/"+cus.ID, e.Acme.Key, nil, &c)
	if c.Name != "Jane Doe" {
		t.Fatalf("customer was changed: %+v", c)
	}
	var i store.Invoice
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv, e.Acme.Key, nil, &i)
	if i.Status != store.InvoiceOpen {
		t.Fatalf("invoice was changed: %+v", i)
	}
	var s store.Subscription
	e.MustDo(http.StatusOK, "GET", "/v1/subscriptions/"+sub, e.Acme.Key, nil, &s)
	if s.Quantity != 1 {
		t.Fatalf("subscription was changed: %+v", s)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusOK, "GET", "/v1/plans/"+plan.ID, e.Acme.Key, nil, nil)
}

