// TestOtherOrgsIDsInBodiesLookUnknown checks that a customer, plan or subscription of another organization named in a body
// is answered exactly as one that does not exist, and that nothing is created or changed.
func TestOtherOrgsIDsInBodiesLookUnknown(t *testing.T) {
	e := apitest.New(t)
	acmeCus := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	acmePlan := e.CreatePlan(e.Acme, "Pro", "USD", "10.00")
	globexCus := e.CreateCustomer(e.Globex, "Gina", "gina@globex.example")
	globexPlan := e.CreatePlan(e.Globex, "Business", "USD", "20.00")
	globexSub := createSubscription(t, e, e.Globex, globexCus.ID, globexPlan.ID)

	line := []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 1000}}
	cases := []struct {
		name, method, path string
		foreign, missing   string
		body               func(id string) any
	}{
		{"invoice for a customer", "POST", "/v1/invoices", acmeCus.ID, "cus_999999",
			func(id string) any { return map[string]any{"customer_id": id, "currency": "USD", "lines": line} }},
		{"subscription for a customer", "POST", "/v1/subscriptions", acmeCus.ID, "cus_999999",
			func(id string) any { return map[string]any{"customer_id": id, "plan_id": globexPlan.ID} }},
		{"subscription on a plan", "POST", "/v1/subscriptions", acmePlan.ID, "plan_999999",
			func(id string) any { return map[string]any{"customer_id": globexCus.ID, "plan_id": id} }},
		{"subscription change to a plan", "PATCH", "/v1/subscriptions/" + globexSub, acmePlan.ID, "plan_999999",
			func(id string) any { return map[string]any{"plan_id": id} }},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			foreign := e.Do(c.method, c.path, e.Globex.Key, c.body(c.foreign))
			unknown := e.Do(c.method, c.path, e.Globex.Key, c.body(c.missing))
			if foreign.Code != http.StatusNotFound || foreign.Map(t)["error"] != "not_found" {
				t.Fatalf("another organization's object: %s", foreign)
			}
			if unknown.Code != foreign.Code || !bytes.Equal(unknown.Body, foreign.Body) {
				t.Fatalf("another organization's object answers %s, an unknown one %s", foreign, unknown)
			}
		})
	}

	// Nothing was created for Globex, and its subscription still has its own plan.
	var invs struct {
		Items []store.Invoice `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices", e.Globex.Key, nil, &invs)
	if len(invs.Items) != 0 {
		t.Fatalf("Globex has invoices it never made: %+v", invs.Items)
	}
	var subs struct {
		Items []store.Subscription `json:"items"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/subscriptions", e.Globex.Key, nil, &subs)
	if len(subs.Items) != 1 || subs.Items[0].ID != globexSub || subs.Items[0].PlanID != globexPlan.ID {
		t.Fatalf("Globex subscriptions = %+v", subs.Items)
	}
}

// TestOtherOrgsIDsInQueriesFindNothing checks that filters by an ID of another organization find nothing.
func TestOtherOrgsIDsInQueriesFindNothing(t *testing.T) {
	e := apitest.New(t)
	cus := e.CreateCustomer(e.Acme, "Jane Doe", "jane@example.com")
	plan := e.CreatePlan(e.Acme, "Pro", "USD", "10.00")
	inv := createInvoice(t, e, e.Acme, cus.ID)
	createSubscription(t, e, e.Acme, cus.ID, plan.ID)
	e.Do("POST", "/v1/invoices/"+inv+"/void", e.Acme.Key, nil)

	for _, path := range []string{
		"/v1/invoices?customer_id=" + cus.ID,
		"/v1/subscriptions?customer_id=" + cus.ID,
		"/v1/payments?invoice_id=" + inv,
		"/v1/customers?email=jane@example.com",
	} {
		var page struct {
			Items []map[string]any `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", path, e.Globex.Key, nil, &page)
		if len(page.Items) != 0 {
			t.Fatalf("GET %s found another organization's objects: %v", path, page.Items)
		}
	}
}

// TestEmailsArePerOrganization checks that two organizations can each have a customer with the same email address, and that
// each finds, reuses and changes only its own.
func TestEmailsArePerOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := e.CreateCustomer(e.Acme, "Jane Acme", "jane@example.com")
	globex := e.CreateCustomer(e.Globex, "Jane Globex", "Jane@Example.com")

	find := func(org apitest.Org, email string) []store.Customer {
		t.Helper()
		var page struct {
			Items []store.Customer `json:"items"`
		}
		e.MustDo(http.StatusOK, "GET", "/v1/customers?email="+email, org.Key, nil, &page)
		return page.Items
	}
	if got := find(e.Acme, "jane@example.com"); len(got) != 1 || got[0].ID != acme.ID {
		t.Fatalf("Acme finds %+v, want its own customer %s", got, acme.ID)
	}
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != globex.ID {
		t.Fatalf("Globex finds %+v, want its own customer %s", got, globex.ID)
	}

	// Acme's address is taken within Acme, but not within Globex.
	if r := e.Do("POST", "/v1/customers", e.Acme.Key, map[string]string{"name": "Jane 2", "email": "JANE@example.com"}); r.Code != http.StatusConflict || r.Map(t)["error"] != "email_taken" {
		t.Fatalf("duplicate within Acme: %s", r)
	}

	// Moving Acme's customer to a new address frees the old one in Acme only.
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+acme.ID, e.Acme.Key, map[string]string{"email": "jane.acme@example.com"}, nil)
	if got := find(e.Acme, "jane@example.com"); len(got) != 0 {
		t.Fatalf("Acme still finds the old address: %+v", got)
	}
	if got := find(e.Globex, "jane@example.com"); len(got) != 1 || got[0].ID != globex.ID {
		t.Fatalf("Globex lost its customer when Acme changed its address: %+v", got)
	}

	// Deleting Globex's customer leaves Acme's alone.
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+globex.ID, e.Globex.Key, nil, nil)
	if got := find(e.Acme, "jane.acme@example.com"); len(got) != 1 || got[0].ID != acme.ID {
		t.Fatalf("Acme lost its customer when Globex deleted one: %+v", got)
	}
}

// TestDeleteOwnWebhookEndpointOnly checks that deleting an endpoint of another organization removes nothing.
func TestDeleteOwnWebhookEndpointOnly(t *testing.T) {
	e := apitest.New(t)
	ep := createEndpoint(t, e, e.Acme, "https://hooks.acme.example/tally")
	if r := e.Do("DELETE", "/v1/webhook-endpoints/"+ep, e.Globex.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("Globex deletes Acme's endpoint: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep, e.Acme.Key, nil, nil)
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/webhook-endpoints/"+ep, e.Acme.Key, nil, nil)
	if r := e.Do("GET", "/v1/webhook-endpoints/"+ep, e.Acme.Key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("Acme's own delete did not remove the endpoint: %s", r)
	}
}

