package store

import (
	"errors"
	"testing"

	"example.com/tally/internal/money"
)

// A subscription may only name a customer and a plan of its own organization.
func TestCreateSubscriptionNeedsOwnCustomer(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	foreign, err := s.CreateCustomer(b.ID, "Gina", "gina@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	plan, err := s.CreatePlan(Plan{OrgID: a.ID, Name: "Pro", Currency: money.USD, UnitAmount: 1000, Interval: Monthly}, t0)
	if err != nil {
		t.Fatal(err)
	}
	_, err = s.CreateSubscription(Subscription{OrgID: a.ID, CustomerID: foreign.ID, PlanID: plan.ID, Quantity: 1, Status: Active}, t0)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for another org's customer: %v, want ErrNotFound", err)
	}
	if got := s.Subscriptions(a.ID, SubscriptionFilter{}); len(got) != 0 {
		t.Fatalf("subscription was created: %+v", got)
	}
}

// Deleting an endpoint by ID alone is for the admin tool; the API deletes only within the caller's organization.
func TestDeleteOrgWebhookEndpoint(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	ep, err := s.CreateWebhookEndpoint(WebhookEndpoint{OrgID: a.ID, URL: "https://hooks.acme.example/tally", Events: []string{"*"}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteOrgWebhookEndpoint(b.ID, ep.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("another org deletes the endpoint: %v, want ErrNotFound", err)
	}
	if _, ok := s.WebhookEndpoint(a.ID, ep.ID); !ok {
		t.Fatal("another org's delete removed the endpoint")
	}
	if err := s.DeleteOrgWebhookEndpoint(a.ID, ep.ID); err != nil {
		t.Fatalf("own delete: %v", err)
	}
	if _, ok := s.WebhookEndpoint(a.ID, ep.ID); ok {
		t.Fatal("own delete kept the endpoint")
	}
}

// Two organizations can each have a customer with the same email address, and each finds its own, also after a change of
// address, a deletion and a round trip through Export and FromState.
func TestCustomerEmailIndexIsPerOrganization(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "Acme"), newOrg(t, s, "Globex")
	ca, err := s.CreateCustomer(a.ID, "Jane Acme", "jane@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	cb, err := s.CreateCustomer(b.ID, "Jane Globex", "JANE@example.com", t0)
	if err != nil {
		t.Fatalf("same email in another org: %v", err)
	}
	find := func(st *Store, orgID string) string {
		t.Helper()
		c, ok := st.FindCustomerByEmail(orgID, "jane@example.com")
		if !ok {
			return ""
		}
		return c.ID
	}
	if got := find(s, a.ID); got != ca.ID {
		t.Fatalf("Acme finds %s, want %s", got, ca.ID)
	}
	if got := find(s, b.ID); got != cb.ID {
		t.Fatalf("Globex finds %s, want %s", got, cb.ID)
	}
	if _, err := s.CreateCustomer(a.ID, "Jane 2", "jane@example.com", t0); !errors.Is(err, ErrEmailTaken) {
		t.Fatalf("second Acme customer with the address: %v, want ErrEmailTaken", err)
	}

	if _, err := s.UpdateCustomer(a.ID, ca.ID, func(c *Customer) error { c.Email = "acme.jane@example.com"; return nil }); err != nil {
		t.Fatal(err)
	}
	if got := find(s, a.ID); got != "" {
		t.Fatalf("Acme still finds the old address: %s", got)
	}
	if got := find(s, b.ID); got != cb.ID {
		t.Fatalf("Globex lost its customer when Acme changed its address: %s", got)
	}
	if err := s.DeleteCustomer(b.ID, cb.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateCustomer(a.ID, "Jane 3", "jane@example.com", t0); err != nil {
		t.Fatalf("address freed in Acme but not taken: %v", err)
	}

	restored, err := FromState(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if got := find(restored, a.ID); got == "" || got == ca.ID {
		t.Fatalf("restored Acme finds %q", got)
	}
	if _, ok := restored.FindCustomerByEmail(b.ID, "jane@example.com"); ok {
		t.Fatal("restored Globex finds a customer it deleted")
	}
}

